# Generated by Claudian.
"""Skill: empty the Trash."""

from ai.response_generator import ResponseGenerator
from automation.system_control import clear_trash
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult


class EmptyTrashSkill(Skill):
    name = "empty_trash"
    description = "Empty the macOS Trash"
    priority = 15

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        low = text.lower()
        if "empty" in low and "trash" in low:
            return SkillMatch(confidence=0.95)
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        # Gated: irreversible. The gate lives in core/confirmation.py so
        # this skill cannot approve itself.
        async def _do() -> str:
            ok = await run_in_thread(clear_trash)
            return "Trash emptied." if ok else "I couldn't empty the Trash."

        from core.confirmation import PendingAction
        return SkillResult(
            text="Empty the Trash permanently? Say yes to confirm.",
            confirm=PendingAction(description="empty the Trash", run=_do),
        )
